{"content": "1|#!/usr/bin/env python3
2|"""Gera a expressao JS (ASCII puro) que sincroniza UM card do Trello pelo navegador nativo.
3|
4|Uso:
5|    python acirv_trello_desc_js.py <POST_ID> <CARD_SHORTLINK>
6|
7|Le o bloco "### DESCRICAO CANONICA PARA O TRELLO" no arquivo mensal canonico
8|(01-planejamento/v2/2026-*.md) e imprime em stdout UMA expressao JS (IIFE
9|assincrona) que, executada na aba do card ja aberta:
10|
11|  1. confere que a aba esta no card esperado (location.pathname);
12|  2. abre o editor de descricao (ProseMirror) por seletores ASCII;
13|  3. substitui INTEGRALMENTE o conteudo pelo texto canonico (sem edicao);
14|  4. clica em Salvar;
15|  5. rele o card pela API (/1/cards/<id>) e valida tamanho, acentuacao,
16|     sentinela, ausencia de metadados internos e prefixo identico;
17|  6. devolve UMA string escalar: "SAVED_OK" ou "FAIL:<CODIGO>".
18|
19|O texto viaja em base64 (ASCII) e e decodificado dentro da pagina, evitando
20|qualquer corrupcao de acentuacao no transporte. O JS nao usa nenhum caractere
21|nao-ASCII (nem em seletores) para nao depender da codificacao do transporte.
22|
23|Nao escreve em disco. Nao toca no Trello por conta propria.
24|"""
25|import base64
26|import pathlib
27|import re
28|import sys
29|
30|BASE = pathlib.Path("C:/Github/ACIRV-Notebook/Hermes")
31|HEADING = "### DESCRI" + "\u00c7\u00c3O CAN\u00d4NICA PARA O TRELLO"
32|
33|JS_TEMPLATE = r"""(async () => {
34|  const CARD = "__CARD__";
35|  const B64 =
36|  __B64__;
37|  let TEXTO = "";
38|  try {
39|    TEXTO = new TextDecoder("utf-8").decode(Uint8Array.from(atob(B64), (c) => c.charCodeAt(0)));
40|  } catch (e) { return "FAIL:B64"; }
41|  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
42|  const ACC = [225,224,226,227,233,234,237,243,244,245,250,252,231,193,192,194,195,201,202,205,211,212,213,218,220,199];
43|  const acc = (s) => { let n = 0; for (let i = 0; i < s.length; i++) { if (ACC.indexOf(s.charCodeAt(i)) >= 0) n++; } return n; };
44|  const norm = (s) => s.replace(/\s+/g, " ").trim();
45|  const api = (p) => { const x = new XMLHttpRequest(); x.open("GET", p + "&_=" + Date.now(), false); x.send(); return JSON.parse(x.responseText); };
46|  if (location.pathname.indexOf("/c/" + CARD) !== 0) return "FAIL:WRONG_CARD";
47|  try { api("/1/cards/" + CARD + "?fields=name,desc,due"); } catch (e) { return "FAIL:API_READ"; }
48|  const edPick = () => {
49|    let el = document.querySelector('.ProseMirror[aria-label*="descri" i]');
50|    if (el) return el;
51|    const all = Array.from(document.querySelectorAll(".ProseMirror"));
52|    for (const c of all) {
53|      const lab = c.getAttribute("aria-label") || "";
54|      if (/descri/i.test(lab)) return c;
55|      if (c.closest('[data-testid*="description"], [class*="description"]')) return c;
56|    }
57|    return null;
58|  };
59|  let ed = edPick();
60|  if (!ed) {
61|    let btn = document.querySelector('[data-testid="description-button"]');
62|    if (!btn) {
63|      const cands = Array.from(document.querySelectorAll("button, [role='button'], a"));
64|      btn = cands.find((b) => /editar|descri/i.test(b.getAttribute("aria-label") || "") || /editar|descri/i.test(b.textContent || "")) || null;
65|    }
66|    if (!btn) return "FAIL:NO_EDIT_BUTTON";
67|    btn.click();
68|    for (let i = 0; i < 10 && !ed; i++) { await sleep(120); ed = edPick(); }
69|  }
70|  if (!ed) return "FAIL:NO_EDITOR";
71|  ed.focus();
72|  document.execCommand("selectAll");
73|  await sleep(120);
74|  document.execCommand("delete");
75|  await sleep(200);
76|  const dt = new DataTransfer();
77|  dt.setData("text/plain", TEXTO);
78|  ed.dispatchEvent(new ClipboardEvent("paste", {clipboardData: dt, bubbles: true, cancelable: true}));
79|  await sleep(250);
80|  if ((ed.innerText || "").length < 200) return "FAIL:PASTE_EMPTY";
81|  let save = document.querySelector('[data-testid="description-save-button"]');
82|  if (!save) {
83|    save = Array.from(document.querySelectorAll("button")).find((b) => /salvar/i.test(b.textContent || "")) || null;
84|  }
85|  if (!save) return "FAIL:NO_SAVE_BUTTON";
86|  save.click();
87|  await sleep(600);
88|  let after = null;
89|  try { after = api("/1/cards/" + CARD + "?fields=name,desc,due"); } catch (e) { return "FAIL:API_AFTER"; }
90|  const d = (after && after.desc) || "";
91|  if (d.length < TEXTO.length - 2) return "FAIL:LEN";
92|  if (acc(d) !== acc(TEXTO)) return "FAIL:ACC";
93|  if (d.indexOf("DATA DE ENTREGA") < 0) return "FAIL:SENTINEL";
94|  if (d.indexOf("POST ID") >= 0) return "FAIL:META";
95|  if (norm(d).slice(0, 150) !== norm(TEXTO).slice(0, 150)) return "FAIL:PREFIX";
96|  return "SAVED_OK";
97|})()"""
98|
99|
100|def monthly_files():
101|    return sorted(BASE.glob("*/01-planejamento/v2/2026-*.md"))
102|
103|
104|def extract(post_id):
105|    hits = []
106|    for path in monthly_files():
107|        lines = path.read_text(encoding="utf-8").splitlines()
108|        start = None
109|        for i, line in enumerate(lines):
110|            if line.startswith("## ") and post_id in line:
111|                start = i
112|                break
113|        if start is None:
114|            continue
115|        head = None
116|        for j in range(start + 1, len(lines)):
117|            if lines[j].strip() == HEADING:
118|                head = j
119|                break
120|            if lines[j].startswith("## "):
121|                break
122|        if head is None:
123|            continue
124|        fence = None
125|        for k in range(head + 1, len(lines)):
126|            if lines[k].strip().startswith("```"):
127|                fence = k
128|                break
129|        if fence is None:
130|            continue
131|        body = []
132|        for m in range(fence + 1, len(lines)):
133|            if lines[m].strip() == "```":
134|                break
135|            body.append(lines[m])
136|        text = "\n".join(body)
137|        if text.strip():
138|            hits.append((path.name, text))
139|    if not hits:
140|        raise SystemExit("BLOCK_NOT_FOUND " + post_id)
141|    if len(hits) > 1:
142|        raise SystemExit("BLOCK_AMBIGUOUS " + post_id + " " + ",".join(h[0] for h in hits))
143|    return hits[0]
144|
145|
146|def b64_literal(text, width=100):
147|    raw = base64.b64encode(text.encode("utf-8")).decode("ascii")
148|    chunks = [raw[i:i + width] for i in range(0, len(raw), width)]
149|    return " +\n  ".join('"' + c + '"' + ("" if i == len(chunks) - 1 else "") for i, c in enumerate(chunks))
150|
151|
152|def main():
153|    if len(sys.argv) != 3:
154|        raise SystemExit("uso: acirv_trello_desc_js.py <POST_ID> <CARD_SHORTLINK>")
155|    post_id, card = sys.argv[1], sys.argv[2]
156|    if not re.fullmatch(r"[A-Za-z0-9]{6,12}", card):
157|        raise SystemExit("CARD_INVALIDO " + card)
158|    name, text = extract(post_id)
159|    if len(text) < 300 or "DATA DE ENTREGA" not in text:
160|        raise SystemExit("BLOCK_SUSPEITO " + post_id + " " + name + " " + str(len(text)))
161|    js = JS_TEMPLATE.replace("__B64__", b64_literal(text)).replace("__CARD__", card)
162|    sys.stdout.write(js)
163|    sys.stdout.write("\n")
164|
165|
166|if __name__ == "__main__":
167|    main()", "total_lines": 167, "file_size": 6678, "truncated": false, "is_binary": false, "is_image": false}

