HEADING = "### DESCRIÇÃO CANÔNICA PARA O TRELLO"


def extract(post_id):
    hits = []
    for path in sorted(BASE.glob("*/01-planejamento/v2/2026-*.md")):
        lines = path.read_text(encoding="utf-8").splitlines()
        start = None
        for i, ln in enumerate(lines):
            if ln.startswith("## ") and post_id in ln:
                start = i
                break
        if start is None:
            continue
        head = None
        for j in range(start + 1, len(lines)):
            if lines[j].strip() == HEADING:
                head = j
                break
            if lines[j].startswith("## "):
                break
        if head is None:
            continue
        fence = None
        for k in range(head + 1, len(lines)):
            if lines[k].strip().startswith("```"):
                fence = k
                break
        if fence is None:
            continue
        body = []
        for m in range(fence + 1, len(lines)):
            if lines[m].strip() == "```":
                break
            body.append(lines[m])
        t = "\n".join(body)
        if t.strip():
            hits.append((path.name, t))
    if not hits:
        raise SystemExit("BLOCK_NOT_FOUND " + post_id)
    if len(hits) > 1:
        raise SystemExit("BLOCK_AMBIGUOUS")
    return hits[0]


