  const acc = (s) => { let n = 0; for (let i = 0; i < s.length; i++) { if (ACC.indexOf(s.charCodeAt(i)) >= 0) n++; } return n; };
  const norm = (s) => s.replace(/\s+/g, " ").trim();
  const api = (p) => { const x = new XMLHttpRequest(); x.open("GET", p + "&_=" + Date.now(), false); x.send(); return JSON.parse(x.responseText); };
  if (location.pathname.indexOf("/c/" + CARD) !== 0) return "FAIL:WRONG_CARD";
  try { api("/1/cards/" + CARD + "?fields=name,desc,due"); } catch (e) { return "FAIL:API_READ"; }
