    let btn = document.querySelector('[data-testid="description-button"]');
    if (!btn) {
      const cands = Array.from(document.querySelectorAll("button, [role='button'], a"));
      btn = cands.find((b) => /editar|descri/i.test(b.getAttribute("aria-label") || "") || /editar|descri/i.test(b.textContent || "")) || null;
    }
    if (!btn) return "FAIL:NO_EDIT_BUTTON";
    btn.click();
    for (let i = 0; i < 10 && !ed; i++) { await sleep(120); ed = edPick(); }
  }
  if (!ed) return "FAIL:NO_EDITOR";
  ed.focus();
  document.execCommand("selectAll");
  await sleep(120);
  document.execCommand("delete");
  await sleep(200);
  const dt = new DataTransfer();
  dt.setData("text/plain", TEXTO);
  ed.dispatchEvent(new ClipboardEvent("paste", {clipboardData: dt, bubbles: true, cancelable: true}));
  await sleep(250);
  if ((ed.innerText || "").length < 200) return "FAIL:PASTE_EMPTY";
  let save = document.querySelector('[data-testid="description-save-button"]');
  if (!save) {
    save = Array.from(document.querySelectorAll("button")).find((b) => /salvar/i.test(b.textContent || "")) || null;
  }
  if (!save) return "FAIL:NO_SAVE_BUTTON";
