  return "SAVED_OK";
})()'''


def chunks(b64, w=100):
    parts = [b64[i:i + w] for i in range(0, len(b64), w)]
    return " +\n  ".join('"' + p + '"' for p in parts)


def main():
    if len(sys.argv) < 3:
        raise SystemExit("uso: emit_gz.py <POST_ID> <CARD> [--raw]")
    post_id, card = sys.argv[1], sys.argv[2]
    raw = "--raw" in sys.argv
    name, text = extract(post_id)
    gz = base64.b64encode(gzip.compress(text.encode("utf-8"), 9)).decode("ascii")
    js = (TEMPLATE.replace("__CARD__", card)
                  .replace("__GZ__", '"' + gz + '"')
                  .replace("__HEAD__", "// %s len=%d gz=%d" % (post_id, len(text), len(gz))))
    if raw:
        sys.stdout.write(js)
    else:
        sys.stdout.write(js)
    sys.stdout.write("\n")


if __name__ == "__main__":
    main()
