{"content": "#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Serve as descricoes canonicas para a aba do Trello ler.

  GET /ping            -> OK
  GET /t/<shortLink>   -> text/plain  (texto canonico)
  GET /n/<shortLink>   -> text/html    (define window.name = texto; sobrevive a navegacao)

O endpoint /n/ existe porque o CSP do Trello bloqueia fetch/XHR para
127.0.0.1 (connect-src), mas NAO bloqueia navegacao de topo. Assim o texto
chega a pagina do Trello via window.name, sem transcrever base64 a mao.
"""
import json
import sys
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

sys.path.insert(0, "C:/Users/Kevyn Lucas/AppData/Local/hermes/scripts")
import acirv_trello_desc_js as gen  # noqa: E402

MAP = {
    "010": "e5aTOk0b", "012": "06CujNRX", "048": "dX4f4Od6", "013": "vPrFs6eb",
    "049": "xbZpm7fc", "015": "fTtL5b3a", "016": "tVCcF9al", "050": "JaQJOhkh",
    "018": "MZJgoU1Y", "019": "Kk8sIyKz", "051": "765HsVfp", "021": "v6ho8Kdr",
    "052": "GpAqPXl1", "022": "9LKVAHb5", "024": "8P4KFJT2", "053": "YrXaznJW",
    "025": "6h7ipocE", "026": "vmjgTXsr", "054": "A0A4GxYQ", "028": "eWbqOL2J",
    "029": "FQkzpdr1", "055": "nbjpMXUf", "031": "F9JBoLci", "056": "P7iGEunQ",
    "034": "nVMO124D", "035": "r2OC0FSZ", "057": "U09QARw3", "037": "nhuq3q43",
    "058": "Wi0aQ539", "039": "OFVbk1m9", "059": "5WmzMkY6", "043": "NSuqd1gP",
    "060": "Ps53LuUd",
}

TEXTS = {}
for _pid, _link in MAP.items():
    _name, _text = gen.extract("ACIRV-SM-2026-" + _pid)
    TEXTS[_link] = _text


class H(BaseHTTPRequestHandler):
    def log_message(self, *a):
        pass

    def _send(self, code, ctype, body):
        b = body.encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(b)))
        self.send_header("Access-Control-Allow-Origin", "*")
        self.end_headers()
        self.wfile.write(b)

    def do_GET(self):
        p = self.path.split("?")[0]
        if p == "/ping":
            return self._send(200, "text/plain", "OK")
        if p.startswith("/t/") or p.startswith("/n/"):
            key = p[3:]
            if key not in TEXTS:
                return self._send(404, "text/plain", "NOT_FOUND")
            if p.startswith("/t/"):
                return self._send(200, "text/plain; charset=utf-8", TEXTS[key])
            js = json.dumps(TEXTS[key], ensure_ascii=False).replace("<", "\\u003c")
            html = ('<!doctype html><meta charset="utf-8"><body>NAME_SET'
                    '<script>window.name=' + js + ';</script>')
            return self._send(200, "text/html; charset=utf-8", html)
        return self._send(404, "text/plain", "NOT_FOUND")


if __name__ == "__main__":
    port = int(sys.argv[1]) if len(sys.argv) > 1 else 8798
    srv = ThreadingHTTPServer(("127.0.0.1", port), H)
    print("SERVING %d cards on %d" % (len(TEXTS), port), flush=True)
    srv.serve_forever()
